 accepted={'issue':'HKS-214','sourceReports':reports,'views':views,'acceptedViewCount':40,'uniqueNativeParts':13,'normalScene':True,'dataInterception':False,'sourceGeometryChanged':False,'qualification':'Browser checks establish actual loading, picking and framing; manual inspection separately holds239278. Earlier close-ups omitted terrain from camera scoring and are superseded by terrain-aware captures.'};save(D/'lantau13-browser-accepted.json',accepted)
 models={m['uid']:m for m in read(HERE/'lantau13-catalogue.json')['models']};proofs={}
