 decision={'issue':'HKS-214','reviewSnapshot':'11a25ce297101f9e','existingNativeParts':13,'newModelsAdded':0,'installedVerified':11,'needsSupportMetadata':1,'heldSourceTerrainConflict':1,'verticalScale':1,'sourceGeometryChanged':False,'rows':rows,'sourceReferences':[{'url':'https://www.taioheritagehotel.com/en/about-us/architecture/','basis':'Owner describes two-storey main block/outhouse, later extension, verandahs, tiled roof and connecting bridge.'},{'url':'https://www.aab.gov.hk/filemanager/aab/common/historicbuilding/en/440_Appraisal_En.pdf','basis':'Government appraisal confirms linked historic blocks, projecting eaves and arched verandahs.'},{'url':'https://www.np360.com.hk/en/things-to-do','basis':'Operator describes Chinese architectural village and landscape design.'}],'limits':['Native government forms retain simplified source architecture; window placement/material colours are procedural, not surveyed textures or heritage ornament reconstruction.','Whole Tai O/Po Lin/Ngong Ping completion is not asserted.','Tai O239278 stays a tracked source conflict even though its existing model remains in the viewer.','Grand Hall238482 also needs its existing podium dependency reconciled in the next review.','Desktop and emulated mobile screenshots do not certify Safari or sustained real-device performance.']};save(D/'lantau13-decisions.json',decision)
 f,url,m=live['landsd/238276:0'];podium=live['landsd/238483:0'][2];contact=D/'lantau13-support.json';assert support[m['uid']]['rimCounts']['otherTriangleContact']==14 and all(any(c['uid']==podium['uid'] and c['distance']<=.5 for c in r['contacts']) for r in support[m['uid']]['rim']);sidecar={'issue':'HKS-214','version':1,'published':False,'scope':'Add exact native podium retention for Hall of Great Hero; all other source fields/assets unchanged.','catalogues':[{'url':url,'source':str(f.relative_to(ROOT)),'oldSHA256':sha(f),'models':[m['uid']]}],'changes':[{'uid':m['uid'],'modelSHA256':m['sha256'],'modelId':m['modelId'],'buildingCSUID':m['buildingCSUID'],'catalogue':str(f.relative_to(ROOT)),'oldSupportDependencies':m.get('supportDependencies',[]),'supportDependencies':[{'uid':podium['uid'],'state':'installed','csuid':podium['buildingCSUID']}],'contactEvidenceSHA256':sha(contact)}],'contactReport':str(contact.relative_to(ROOT)),'contactReportSHA256':sha(contact),'requiresNewNativeUids':[],'requiredExistingNativeUids':[podium['uid']],'requiresVisualApproval':True,'visualApproval':{'status':'approved-for-integration','evidence':str((D/'lantau13-decisions.json').relative_to(ROOT)),'evidenceSHA256':sha(D/'lantau13-decisions.json'),'scope':'All14 native hall rim vertices touch the independently reviewed native podium; actual normal scene day/night desktop/mobile views inspected.'}};save(HERE/'dependency-replacements-polin.json',sidecar);print(json.dumps({'existingReviewed':13,'installedVerified':11,'needsDependency':1,'held':1,'newAssets':0}))
